-- Owner follow-up. Version marker makes point grants idempotent.
UPDATE tn2_characters SET
 skill_points=LEAST(CASE WHEN job_id='villager' THEN 10 WHEN job_id IN ('guardian','berserker','ranger','marksman','wizard','sage','physician','alchemist','spirit_master','exorcist','champion','monk','assassin','shadow') THEN 70 ELSE 50 END,
 skill_points+CASE WHEN jobs_version=0 THEN 1 WHEN job_id='villager' THEN 1 WHEN job_id IN ('guardian','berserker','ranger','marksman','wizard','sage','physician','alchemist','spirit_master','exorcist','champion','monk','assassin','shadow') THEN 3 ELSE 2 END+COALESCE((skills->>'first_aid')::integer,0)+COALESCE((skills->>'survival')::integer,0)),
 skills=CASE WHEN job_id='villager' THEN skills-'first_aid'-'survival' ELSE (skills-'first_aid'-'survival'-'punch')||jsonb_build_object('fighter_basics',COALESCE((skills->>'punch')::integer,(skills->>'fighter_basics')::integer,0)) END,
 hotbar=CASE WHEN hotbar='[{"key":"KeyQ","skill":"basic"},{"key":"KeyE","skill":"dodge"},{"key":"Digit1","skill":null},{"key":"Digit2","skill":null},{"key":"Digit3","skill":null},{"key":"Digit4","skill":null},{"key":"Digit5","skill":"potion"},{"key":"Digit6","skill":null},{"key":"Digit7","skill":null},{"key":"Digit8","skill":null}]'::jsonb OR hotbar='[{"key":"KeyQ","skill":"whirlwind"},{"key":"KeyE","skill":"earth_break"},{"key":"Digit1","skill":null},{"key":"Digit2","skill":null},{"key":"Digit3","skill":null},{"key":"Digit4","skill":null},{"key":"Digit5","skill":"potion"},{"key":"Digit6","skill":null},{"key":"Digit7","skill":null},{"key":"Digit8","skill":null}]'::jsonb THEN CASE WHEN job_id='villager' THEN '[{"key":"Digit1","skill":"punch"},{"key":"Digit2","skill":null},{"key":"Digit3","skill":null},{"key":"Digit4","skill":null},{"key":"Digit5","skill":null},{"key":"Digit6","skill":null},{"key":"Digit7","skill":null},{"key":"Digit8","skill":null},{"key":"Digit9","skill":null},{"key":"Digit0","skill":null}]'::jsonb ELSE '[{"key":"Digit1","skill":"slash"},{"key":"Digit2","skill":"whirlwind"},{"key":"Digit3","skill":"dash_strike"},{"key":"Digit4","skill":"earth_break"},{"key":"Digit5","skill":"endure"},{"key":"Digit6","skill":"provoke"},{"key":"Digit7","skill":null},{"key":"Digit8","skill":null},{"key":"Digit9","skill":null},{"key":"Digit0","skill":null}]'::jsonb END ELSE COALESCE((SELECT jsonb_agg(CASE WHEN slot->>'skill' IN ('first_aid','survival') OR (slot->>'skill'='punch' AND job_id<>'villager') THEN jsonb_set(slot,'{skill}','null'::jsonb) ELSE slot END ORDER BY ord) FROM jsonb_array_elements(hotbar) WITH ORDINALITY AS entries(slot,ord)),'[]'::jsonb) END,
 jobs_version=2 WHERE jobs_version<2;
ALTER TABLE tn2_characters ALTER COLUMN skill_points SET DEFAULT 1;
ALTER TABLE tn2_characters ALTER COLUMN jobs_version SET DEFAULT 2;
ALTER TABLE tn2_characters ALTER COLUMN hotbar SET DEFAULT '[{"key":"Digit1","skill":"punch"},{"key":"Digit2","skill":null},{"key":"Digit3","skill":null},{"key":"Digit4","skill":null},{"key":"Digit5","skill":null},{"key":"Digit6","skill":null},{"key":"Digit7","skill":null},{"key":"Digit8","skill":null},{"key":"Digit9","skill":null},{"key":"Digit0","skill":null}]';
